// Build Request (v12, slice 2): the row for a room request - real Slack ids, names from Bookers, the booking's engineer as a
// second approver (priority requests), and the same request asked again returns the open one. Deadlines as since 25 Sep.
const c = $('When Executed by Another Workflow').first().json || {};

function computeDeadline(now,start,cfg){const n=new Date(now).getTime();const s=new Date(start).getTime();const w=(cfg&&cfg.maxWindowH?cfg.maxWindowH:24)*3600*1000;const l=(cfg&&cfg.minLeadMin?cfg.minLeadMin:60)*60*1000;return new Date(Math.max(n,Math.min(n+w,s-l))).toISOString();}
const MNL_TZ = 8 * 3600 * 1000;
function manilaDayIndex(ms) { return Math.floor((ms + MNL_TZ) / 86400000); }
// v58 (decided 29 Oct): an all-day request is settled before its day starts - 2+ days ahead 24 h (never past the day's 12:00 AM),
// tomorrow 6:00 PM the evening before (at least 1 h, never past midnight), today 1 h (the day has begun; before v58 an all-day
// start of 12:00 AM capped it at "now", and the Sweep handed the booth over within minutes). Timed requests as before.
function mboothDeadline(nowISO, startISO, cfg, allDay) {
  const k = cfg || {};
  const sameDayH = k.sameDayH == null ? 3 : k.sameDayH;
  const farWindowH = k.farWindowH == null ? 24 : k.farWindowH;
  const dayBeforeHour = k.dayBeforeHour == null ? 10 : k.dayBeforeHour;
  const H = 3600 * 1000;
  const now = new Date(nowISO).getTime();
  let start = new Date(startISO).getTime();
  if (/^\d{4}-\d{2}-\d{2}$/.test(String(startISO || '').trim())) { start = Date.parse(String(startISO).trim() + 'T00:00:00+08:00'); allDay = true; }   // a date-only start is all day
  const daysAhead = manilaDayIndex(start) - manilaDayIndex(now);
  let deadline;
  if (allDay) {
    const day0 = manilaDayIndex(start) * 86400000 - MNL_TZ;   // 12:00 AM of the booked day, Manila
    if (daysAhead >= 2) deadline = Math.min(now + farWindowH * H, day0);
    else if (daysAhead === 1) deadline = Math.min(Math.max(day0 - 6 * H, now + H), day0);   // 6:00 PM the evening before
    else deadline = now + H;
    return new Date(Math.max(now, deadline)).toISOString();
  }
  if (daysAhead >= 2) deadline = now + farWindowH * H;
  else if (daysAhead === 1) deadline = (manilaDayIndex(start) * 86400000 - MNL_TZ) + dayBeforeHour * H;
  else deadline = now + sameDayH * H;
  deadline = Math.max(now, Math.min(deadline, start));
  return new Date(deadline).toISOString();
}
// LAUNCH SWITCH (v58): YEAR_SHIFT 1 while testing, 0 at launch (scripts/flip-launch-switches). The booking is a year ahead while
// the clock is real, so the deadline is worked out on its real-year date - otherwise every request looks 2+ days away (24 h).
const YEAR_SHIFT = 1;
function realYear(iso, nowISO) {
  const s = String(iso || '').trim();
  if (!YEAR_SHIFT || !/^\d{4}-/.test(s)) return s;
  const back = String(Number(s.slice(0, 4)) - YEAR_SHIFT) + s.slice(4);
  const b = /^\d{4}-\d{2}-\d{2}$/.test(back) ? Date.parse(back + 'T00:00:00+08:00') : Date.parse(back);
  return manilaDayIndex(b) >= manilaDayIndex(new Date(nowISO).getTime()) ? back : s;   // already past in the real year -> as is
}
function requestDeadline(kind, nowISO, startISO, allDay) {
  const st = realYear(startISO, nowISO);
  return String(kind || '').toUpperCase() === 'MBOOTH' ? mboothDeadline(nowISO, st, null, !!allDay) : computeDeadline(nowISO, st, { maxWindowH: 24, minLeadMin: 60 });
}

function readCache(rows) { let best = null;
  for (const r of rows || []) { if (!r || r.cache_key !== 'jessie-reference') continue; let d; try { d = JSON.parse(r.payload); } catch (e) { continue; }
    if (!d || !Array.isArray(d.bookers)) continue; const at = Date.parse(r.refreshed_at || '') || 0; if (!best || at > best.at) best = { at, d }; }
  return best ? best.d : null; }
const data = readCache($('Read Cache').all().map(i => i.json || {})) || { bookers: [] };
const staff = (data.bookers || []).map(b => b.fields || {}).map(f => ({ name: String(f.Name || '').trim(),
  slack: String(f['Slack User ID'] || '').split(/[\s,]+/).filter(Boolean)[0] || '' })).filter(p => p.name && p.slack);
const nameOf = id => (staff.find(p => p.slack === String(id || '')) || {}).name || '';
const kind = String(c.kind || 'PREEMPT').toUpperCase() === 'MBOOTH' ? 'MBOOTH' : 'PREEMPT';
// the booking in the way, read from the calendar (its engineer, times and rooms)
let ev = {}; try { ev = $('Get Incumbent').first().json || {}; } catch (e) { ev = {}; }
if (!ev || !ev.id || ev.error) ev = {};
const desc = String(ev.description || '');
const roomName = x => String(x || '').replace(/^KDC Plaza-Top Level-/i, '').replace(/(?:\s*\([^)]*\))+\s*$/, '').trim();
const evRooms = (ev.attendees || []).filter(a => a.resource || /@resource\.calendar\.google\.com$/i.test(String(a.email || ''))).map(a => roomName(a.displayName)).filter(Boolean);
const mnl = x => new Date(new Date(x).getTime() + 8 * 3600000).toISOString();
const sd = ev.start && ev.start.dateTime, ed = ev.end && ev.end.dateTime;
const inc = ev.id ? { id: ev.id, d: sd ? mnl(sd).slice(0, 10) : String((ev.start && ev.start.date) || ''), s: sd ? mnl(sd).slice(11, 16) : '', e: ed ? mnl(ed).slice(11, 16) : '',
  r: (evRooms.length ? evRooms : [c.room]).join(', '), t: String(ev.summary || c.incumbentTitle || ''), st: ((desc.match(/SType:\s*([^\n|]+)/i) || [])[1] || '').trim() }
  : { id: String(c.incumbentEventId || ''), d: '', s: '', e: '', r: String(c.room || ''), t: String(c.incumbentTitle || ''), st: '' };
// PENDING 80: the booking's engineer answers too (priority requests) - its Engineer line in Bookers, else its team ids
const engName = ((desc.match(/Engineer:\s*([^(|\n]+)/) || [])[1] || '').trim().toLowerCase();
const team = ((desc.match(/team:\s*([^|\n]+)/) || [])[1] || '').split(/[\s,]+/).filter(Boolean);
let eng = (staff.find(p => p.name.toLowerCase() === engName) || {}).slack || '';
if (!eng) eng = team.find(x => x !== c.approver && x !== c.requester) || '';
const approver2 = kind === 'PREEMPT' && eng && eng !== c.approver && eng !== c.requester ? eng : '';
// PENDING 27: the same requester, room and time asked again -> the open request, not a second one
const rows = $('Read Requests').all().map(i => i.json || {}).filter(r => r['Request ID']);
const same = rows.find(r => String(r['Status'] || '').toUpperCase() === 'PENDING' && String(r['Requester'] || '') === String(c.requester || '')
  && String(r['Room/Booth'] || '') === String(c.room || '') && Date.parse(r['Req Start']) === Date.parse(c.reqStart));
const now = new Date().toISOString();
const id = now.replace(/[-:T.]/g, '').slice(0, 14) + '-' + String(c.requester || 'unknown');
// v58: all day - the booking's own flag, a date-only start, or 12:00 AM to 12:00 AM (whole days)
const _allDay = (() => { let pl = {}; try { pl = JSON.parse(c.reqPayload || '{}') || {}; } catch (e) { pl = {}; }
  if (pl.all_day === true || String(pl.all_day) === 'true') return true;
  const s = String(c.reqStart || '').trim(), e = String(c.reqEnd || '').trim();
  if (/^\d{4}-\d{2}-\d{2}$/.test(s)) return true;
  const a = Date.parse(s), b = Date.parse(e), mid = x => ((x + MNL_TZ) % 86400000) === 0;
  return Number.isFinite(a) && Number.isFinite(b) && b > a && mid(a) && mid(b); })();
const deadline = requestDeadline(kind, now, c.reqStart, _allDay);
const holdName = (String(c.incumbentTitle || '').match(/^\s*M\d+\s*-\s*(.+?)\s*$/i) || [])[1] || '';
const row = {
  'Request ID': id, 'Status': 'PENDING', 'Kind': kind,
  'Requester': String(c.requester || ''), 'Requester Name': nameOf(c.requester) || String(c.requesterName || ''),
  'Approver': String(c.approver || ''), 'Approver Name': nameOf(c.approver) || String(c.approverName || '') || holdName,
  'Room/Booth': String(c.room || ''), 'Req Start': String(c.reqStart || ''), 'Req End': String(c.reqEnd || ''),
  'Incumbent Event Id': String(c.incumbentEventId || ''), 'Incumbent Title': String(c.incumbentTitle || ''),
  'Incumbent New Start': '', 'Incumbent New End': '',
  'Req Priority': (c.reqPriority == null ? '' : c.reqPriority), 'Inc Priority': (c.incPriority == null ? '' : c.incPriority),
  'Deadline': deadline, 'Requester DM': '', 'Approver DM': '', 'Log Thread TS': '', 'Resolved Via': '', 'Attested By': '', 'Decided At': '',
  'Req Payload': (c.reqPayload == null ? '' : (typeof c.reqPayload === 'string' ? c.reqPayload : JSON.stringify(c.reqPayload))),
  'Approver 2': approver2, 'Approver 2 Name': nameOf(approver2), 'Messages': JSON.stringify({ m: [], inc }), 'Withdrawn At': ''
};
const R = same || row;
const asked = kind === 'MBOOTH' ? (R['Approver Name'] || 'the holder')
  : [R['Approver Name'] ? R['Approver Name'] + ' (booker)' : '', R['Approver 2 Name'] ? R['Approver 2 Name'] + ' (engineer)' : ''].filter(Boolean).join(' and ');
return [{ json: { dup: !!same, row, existing: same || null, inc, asked } }];

// Inlined from workflows/drafts/consent/open-request.js + M-Booth wording (Kind=MBOOTH).
const c = $('When Executed by Another Workflow').first().json || {};
const R = $('Build Request').first().json.row || {};
function whenPhrase(s,e){try{if(/^\d{4}-\d{2}-\d{2}$/.test(String(s||''))){return new Date(s+'T00:00:00+08:00').toLocaleDateString('en-US',{timeZone:'Asia/Manila',month:'short',day:'numeric'})+' (all day)';}const o={timeZone:'Asia/Manila',month:'short',day:'numeric',hour:'numeric',minute:'2-digit'};const a=new Date(s).toLocaleString('en-US',o);const b=e?new Date(e).toLocaleTimeString('en-US',{timeZone:'Asia/Manila',hour:'numeric',minute:'2-digit'}):'';return b?(a+'\u2013'+b):a;}catch(_){return String(s||'');}}
const when = c.reqStart ? whenPhrase(c.reqStart, c.reqEnd) : 'the requested time';
const isMB = String(c.kind||'PREEMPT').toUpperCase()==='MBOOTH';
let incumbentDM, requesterReply, approvalsLog;
if(isMB){
  incumbentDM = `Hi ${c.approverName||'there'} \u2014 ${c.requesterName||'someone'} would like to use ${c.room} on ${when}. ${c.room} is your standing booth, so I'm checking with you first. OK to let them use it this once? Reply here with yes or no.`;
  requesterReply = `${c.room} is ${c.approverName||'the holder'}'s standing booth, so I've asked ${c.approverName||'them'} whether you can use it on ${when} \u2014 I'll confirm once they reply. If you've already cleared it with them, reply \"cleared with ${c.approverName||'them'}\".`;
  approvalsLog = `[MBOOTH] ${R['Request ID']} \u2014 PENDING\n${c.requesterName} wants ${c.room} (${when}) for ${c.reqType}. Asked holder ${c.approverName} by DM. Deadline ${R['Deadline']}.`;
} else {
  incumbentDM = `Hi ${c.approverName||'there'} \u2014 ${c.requesterName||'someone'} needs ${c.room} on ${when} for a higher-priority ${c.reqType||'session'}, which would mean moving your \"${c.incumbentTitle}\". Are you OK to move it? If yes, just tell me what time works for your session and I'll sort it out. Reply here with yes or no.`;
  requesterReply = `${c.room} is held by \"${c.incumbentTitle}\" (${c.approverName}) at ${when}. Your ${c.reqType||'session'} outranks it, so I've asked ${c.approverName} to move \u2014 I'll confirm once they reply. If you've already cleared it with them, reply \"cleared with ${c.approverName}\".`;
  approvalsLog = `[PREEMPT] ${R['Request ID']} \u2014 PENDING\n${c.requesterName} wants ${c.room} (${when}) for ${c.reqType} (rank ${R['Req Priority']}) over \"${c.incumbentTitle}\" / ${c.approverName} (rank ${R['Inc Priority']}).\nAsked ${c.approverName} by DM. Deadline ${R['Deadline']}.`;
}
return [{ json: { incumbentDM, requesterReply, approvalsLog, approver: c.approver||'', approverDM: c.approverDM||'' } }];

// v12: the request id, its deadline and who was asked - for the form's "Request sent" (Book Session v120)
const B = $('Build Request').first().json;
return [{ json: { status: 'PENDING', request_id: B.row['Request ID'], deadline: B.row['Deadline'], asked: B.asked || '',
  message: 'Asked ' + (B.asked || 'the holder') + ' for ' + B.row['Room/Booth'] + '.' } }];

// The same request is already open (PENDING 27) - nothing new is written or sent.
const B = $('Build Request').first().json, R = B.existing || {};
return [{ json: { status: 'PENDING', existing: true, request_id: R['Request ID'] || '', deadline: R['Deadline'] || '', asked: B.asked || '',
  message: 'You already asked for ' + (R['Room/Booth'] || 'this room') + ' then - that request is still open.' } }];

// where each message went - kept on the row so they can be updated when the request ends
const B = $('Build Request').first().json;
const r = $input.first().json || {};
return [{ json: { 'Request ID': B.row['Request ID'], 'Messages': JSON.stringify({ m: Array.isArray(r.messages) ? r.messages : [], inc: B.inc }) } }];
